(function () {
  var XHTML = "http://www.w3.org/1999/xhtml";
  var MAIN = "index.html";
  var pages = {"index.html": "", "404.html": "", "ai.html": "", "chat.html": "", "geekedsites.html": "", "googleb87ff79a93e37e5d.html": "", "math.html": "", "movies.html": "", "oibf.html": "", "reading.html": "", "science.html": "", "soundboard.html": "", "pages/1datedanger.html": "", "pages/3dash.html": "", "pages/404.html": "", "pages/60secondsburgerrun.html": "", "pages/99nights.html": "", "pages/academytale.html": "", "pages/adanceoffireandice.html": "", "pages/amongus.html": "", "pages/angrybirds.html": "", "pages/animalcrossing.html": "", "pages/appel.html": "", "pages/asmallworldcup.html": "", "pages/badmondaysimulator.html": "", "pages/badtimesim.html": "", "pages/baldisbasics.html": "", "pages/basketballbros.html": "", "pages/basketballstars.html": "", "pages/basketrandom.html": "", "pages/BERGENTRUCK201x.html": "", "pages/bfdia5b.html": "", "pages/bindingofisacclamb.html": "", "pages/bindingofisacclambeternal.html": "", "pages/bitlife.html": "", "pages/bladeball.html": "", "pages/blockblast.html": "", "pages/blockysnakes.html": "", "pages/bloodmoney.html": "", "pages/bloonstd1.html": "", "pages/bloonstd2.html": "", "pages/bloonstd3.html": "", "pages/bloonstd4.html": "", "pages/bloonstd5.html": "", "pages/bloxorz.html": "", "pages/boomslingers.html": "", "pages/bossslayer.html": "", "pages/bouncemasters.html": "", "pages/bowmasters.html": "", "pages/brawlstars.html": "", "pages/cactusmccoy.html": "", "pages/cactusmccoy2.html": "", "pages/capuchin.html": "", "pages/clashofvikings.html": "", "pages/cloverpit.html": "", "pages/cookieclicker.html": "", "pages/cuphead.html": "", "pages/dborigins.html": "", "pages/dborigins2.html": "", "pages/dbzdevolution.html": "", "pages/ddlc.html": "", "pages/deltarune.html": "", "pages/deltatraveler.html": "", "pages/doodlejump.html": "", "pages/dragonvsbricks.html": "", "pages/drawclimber.html": "", "pages/driftboss.html": "", "pages/drivemad.html": "", "pages/ducklife.html": "", "pages/ducklife2.html": "", "pages/ducklife3.html": "", "pages/ducklife4.html": "", "pages/ducklife5.html": "", "pages/dylanclient.html": "", "pages/escaperoad.html": "", "pages/fireboyandwatergirl.html": "", "pages/flyinggorilla.html": "", "pages/fnaf1.html": "", "pages/fnaf2.html": "", "pages/fnaf3.html": "", "pages/fnaf4.html": "", "pages/fnaf5.html": "", "pages/fnaf6.html": "", "pages/fnafworld.html": "", "pages/fnf.html": "", "pages/fnfbfdi26.html": "", "pages/footballbros.html": "", "pages/fortzone.html": "", "pages/geometrydashlite.html": "", "pages/getyoked.html": "", "pages/gladihoppers.html": "", "pages/googlebaseball.html": "", "pages/granny.html": "", "pages/gswitch3.html": "", "pages/gswitch4.html": "", "pages/gunspin.html": "", "pages/helixjump.html": "", "pages/karlson2d.html": "", "pages/minecraft.html": "", "pages/motox3m.html": "", "pages/motox3m2.html": "", "pages/myteardrop.html": "", "pages/paperio.html": "", "pages/peopleplayground.html": "", "pages/qwop.html": "", "pages/ragdollarchers.html": "", "pages/ragdollhit.html": "", "pages/ragdollio.html": "", "pages/redball4vol1.html": "", "pages/roaringknightremake.html": "", "pages/sandboxels.html": "", "pages/sandtris.html": "", "pages/skyriders.html": "", "pages/slimerancher.html": "", "pages/slitherio.html": "", "pages/slope.html": "", "pages/snake.html": "", "pages/snowballio.html": "", "pages/snowrider3d.html": "", "pages/solarsmash.html": "", "pages/sonicmania.html": "", "pages/sonicroboblast2.html": "", "pages/sonicthehedgehog.html": "", "pages/spacewaves.html": "", "pages/spearofjoestice.html": "", "pages/speedperclick.html": "", "pages/speedstars.html": "", "pages/squidgames.html": "", "pages/stickmanduel.html": "", "pages/stickmanhook.html": "", "pages/stickwar.html": "", "pages/stickwithit.html": "", "pages/subwaysurfers.html": "", "pages/superhot.html": "", "pages/survivalrace.html": "", "pages/survivorio.html": "", "pages/terraria.html": "", "pages/tinyfishing.html": "", "pages/ucn.html": "", "pages/ultrakill.html": "", "pages/undertale.html": "", "pages/undertaleicebound.html": "", "pages/undertaleyellow.html": "", "pages/vex.html": "", "pages/vex2.html": "", "pages/vex3.html": "", "pages/vex4.html": "", "pages/vex5.html": "", "pages/vex6.html": "", "pages/vex7.html": "", "pages/vex8.html": "", "pages/webdashers.html": "", "pages/whg.html": "", "pages/yandresimulator.html": "", "pages/balatroweb/math.html": "", "pages/deltarune/deltarune.html": "", "pages/gtag/fvsvsfv.html": "", "pages/gtag/itworks.html": "", "pages/noomiclone/before.html": ""};
  var keys = Object.keys(pages);
  var current = MAIN;

  async function decode(b) {
    var bin = atob(b), bytes = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    var stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("deflate"));
    return await new Response(stream).text();
  }

  function normalize(p) {
    var out = [];
    p.split("/").forEach(function (s) {
      if (s === "" || s === ".") return;
      if (s === "..") out.pop(); else out.push(s);
    });
    return out.join("/");
  }

  function resolve(raw) {
    var clean = raw.split("#")[0].split("?")[0];
    try { clean = decodeURIComponent(clean); } catch (e) {}
    if (/^[a-z][a-z0-9+.-]*:\/\//i.test(clean)) {
      try { clean = new URL(clean).pathname; } catch (e) {}
      clean = clean.replace(/^\/+/, "");
      var best = null;
      keys.forEach(function (k) {
        if (clean === k || clean.slice(-(k.length + 1)) === "/" + k) {
          if (!best || k.length > best.length) best = k;
        }
      });
      if (best) return best;
    }
    var dir = current.indexOf("/") > -1 ? current.slice(0, current.lastIndexOf("/")) : "";
    var rel = clean.charAt(0) === "/" ? normalize(clean) : normalize(dir + "/" + clean);
    if (pages[rel]) return rel;
    var root = normalize(clean);
    if (pages[root]) return root;
    if (clean === "" || clean === "/") return MAIN;
    var tries = [rel + ".html", rel + "/index.html", root + ".html", root + "/index.html"];
    for (var t = 0; t < tries.length; t++) { if (pages[tries[t]]) return tries[t]; }
    var base = clean.split("/").pop().toLowerCase();
    for (var i = 0; i < keys.length; i++) {
      if (keys[i].split("/").pop().toLowerCase() === base) return keys[i];
    }
    return null;
  }

  var frame = document.createElementNS(XHTML, "iframe");
  frame.setAttribute("style", "width:100%;height:100%;border:0;");
  frame.setAttribute("allow", "fullscreen; autoplay; gamepad; clipboard-write");
  frame.setAttribute("allowfullscreen", "true");
  document.querySelector("foreignObject").appendChild(frame);

  async function show(key) {
    current = key;
    frame.srcdoc = await decode(pages[key]);
  }

  window.addEventListener("message", function (e) {
    if (e.data && e.data.ubgFrame !== undefined) {
      var fk = resolve(String(e.data.ubgFrame));
      var fid = e.data.id, src = e.source;
      if (fk) {
        decode(pages[fk]).then(function (h) { src.postMessage({ ubgHtml: h, id: fid }, "*"); });
      } else {
        if (e.data.kind === "iframe") alert("Game page not bundled: " + e.data.ubgFrame);
        src.postMessage({ ubgHtml: null, id: fid }, "*");
      }
      return;
    }
    if (!e.data || !e.data.ubgNav) return;
    var raw = e.data.ubgNav;
    var key = resolve(raw);
    if (key) { show(key); return; }
    if (/^https?:\/\//i.test(raw)) { window.open(raw, "_blank"); return; }
    alert("Page not bundled: " + raw + "\n(from " + current + ")");
  });

  show(MAIN);
})();
